cat << 'EOF' > chk.py
import numpy as np,sys
f=sys.argv[1]
L=open(f).readlines();n=int(L[0])
el=[l.split()[0] for l in L[2:2+n]];x=np.array([[float(v) for v in l.split()[1:4]] for l in L[2:2+n]])
rh=el.index('Rh')
nb=[i for i in range(n) if i!=rh and np.linalg.norm(x[i]-x[rh])<2.7]
for i in nb: print(i,el[i],round(np.linalg.norm(x[i]-x[rh]),2))
for a in nb:
  for b in nb:
    if a<b:
      u=x[a]-x[rh];v=x[b]-x[rh];ang=np.degrees(np.arccos(u@v/np.linalg.norm(u)/np.linalg.norm(v)))
      if ang>140: print('trans',el[a],a,el[b],b,round(ang))
EOF
